def transform(grid):
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0)
    above = grid[:sep]
    below = grid[sep + 1:]
    # Keep the half with the greater density of the patterned color (8).
    def density(part):
        return sum(v == 8 for row in part for v in row) / max(1, sum(len(row) for row in part))
    chosen = above if density(above) > density(below) else below
    return [[2 if v == 8 else 0 for v in row] for row in chosen]
